import * as THREE from 'three';

// Shared low-poly operator body used by AI bots, bot proxies and remote players.

const PALETTES = {
  hostile: { cloth: 0x44483b, vest: 0x2e3328 },
  blue:    { cloth: 0x32465e, vest: 0x222e3d },
  red:     { cloth: 0x5e3430, vest: 0x3d2320 },
};

const matCache = {};
function mats(kind) {
  if (!matCache[kind]) {
    const p = PALETTES[kind] || PALETTES.hostile;
    matCache[kind] = {
      cloth: new THREE.MeshStandardMaterial({ color: p.cloth, roughness: 0.9 }),
      vest:  new THREE.MeshStandardMaterial({ color: p.vest, roughness: 0.85 }),
      skin:  new THREE.MeshStandardMaterial({ color: 0xb08868, roughness: 0.8 }),
      gun:   new THREE.MeshStandardMaterial({ color: 0x1c1d1f, roughness: 0.5, metalness: 0.55 }),
    };
  }
  return matCache[kind];
}

export function buildSoldier(group, kind = 'hostile') {
  const m = mats(kind);
  const hitboxes = [];
  const add = (geo, mat, x, y, z, part) => {
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(x, y, z);
    mesh.castShadow = true;
    if (part) {
      mesh.userData.part = part;
      hitboxes.push(mesh);
    }
    group.add(mesh);
    return mesh;
  };

  const legL = add(new THREE.BoxGeometry(0.16, 0.85, 0.18), m.cloth, -0.11, 0.425, 0, 'body');
  const legR = add(new THREE.BoxGeometry(0.16, 0.85, 0.18), m.cloth, 0.11, 0.425, 0, 'body');
  add(new THREE.BoxGeometry(0.42, 0.55, 0.24), m.cloth, 0, 1.12, 0, 'body');   // torso
  add(new THREE.BoxGeometry(0.46, 0.4, 0.3), m.vest, 0, 1.12, 0, 'body');      // plate carrier
  add(new THREE.BoxGeometry(0.11, 0.5, 0.13), m.cloth, -0.27, 1.15, 0, 'body'); // left arm
  add(new THREE.BoxGeometry(0.11, 0.45, 0.13), m.cloth, 0.27, 1.18, -0.12, 'body'); // right arm
  const head = add(new THREE.BoxGeometry(0.2, 0.22, 0.2), m.skin, 0, 1.52, 0, 'head');
  add(new THREE.BoxGeometry(0.24, 0.13, 0.24), m.vest, 0, 1.6, 0, 'head');     // helmet
  add(new THREE.BoxGeometry(0.05, 0.07, 0.62), m.gun, 0.13, 1.3, -0.3, null);  // rifle

  const muzzle = new THREE.Object3D();
  muzzle.position.set(0.13, 1.3, -0.62);
  group.add(muzzle);

  return { hitboxes, head, muzzle, legL, legR };
}

export function makeNameTag(text, color = '#9fd4ff') {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 64;
  const g = c.getContext('2d');
  g.font = 'bold 34px "Segoe UI", sans-serif';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.lineWidth = 6;
  g.strokeStyle = 'rgba(0,0,0,0.8)';
  g.strokeText(text, 128, 32);
  g.fillStyle = color;
  g.fillText(text, 128, 32);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: tex, transparent: true, depthTest: false,
  }));
  sprite.scale.set(1.3, 0.33, 1);
  sprite.position.y = 1.95;
  sprite.renderOrder = 999;
  return sprite;
}
